drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  01 · batch-load customers★★★ core
//  concepts: N+1 · batching · in-memory join
// ─────────────────────────────────────────────────────────────────────────
//
//  One round-trip for all related rows, then join in memory.

using static Bootcamp.Check;

async Task<List<OrderRow>> LoadRows(IReadOnlyList<Order> orders, Func<IReadOnlyCollection<int>, Task<Dictionary<int, Customer>>> loadCustomers)
{
    if (orders.Count == 0) return new List<OrderRow>();
    var ids = orders.Select(o => o.CustomerId).Distinct().ToList();
    var customers = await loadCustomers(ids);
    return orders
        .Select(o => new OrderRow(o.Id, customers.TryGetValue(o.CustomerId, out var c) ? c.Name : "(unknown customer)", o.Total))
        .ToList();
}

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("one call with the distinct customer ids", async () =>
{
    var calls = new List<int[]>();
    Task<Dictionary<int, Customer>> Load(IReadOnlyCollection<int> ids)
    {
        calls.Add(ids.OrderBy(i => i).ToArray());
        return Task.FromResult(ids.ToDictionary(i => i, i => new Customer(i, "c" + i)));
    }
    await LoadRows(new[] { new Order(10, 1, 5m), new Order(11, 2, 7m), new Order(12, 1, 9m) }, Load);
    Eq(calls.Count, 1);
    Eq(calls[0], new[] { 1, 2 });
});

Test("rows keep the order sequence and carry the names", async () =>
{
    Task<Dictionary<int, Customer>> Load(IReadOnlyCollection<int> ids) => Task.FromResult(new Dictionary<int, Customer> { [1] = new(1, "Ana"), [2] = new(2, "Bo") });
    var rows = await LoadRows(new[] { new Order(12, 2, 9m), new Order(10, 1, 5m) }, Load);
    Eq(rows, new[] { new OrderRow(12, "Bo", 9m), new OrderRow(10, "Ana", 5m) });
});

Test("a missing customer gets a placeholder name", async () =>
{
    Task<Dictionary<int, Customer>> Load(IReadOnlyCollection<int> ids) => Task.FromResult(new Dictionary<int, Customer>());
    var rows = await LoadRows(new[] { new Order(1, 99, 3m) }, Load);
    Eq(rows[0].CustomerName, "(unknown customer)");
});

Test("no orders, no call (boundary)", async () =>
{
    var calls = 0;
    Task<Dictionary<int, Customer>> Load(IReadOnlyCollection<int> ids) { calls++; return Task.FromResult(new Dictionary<int, Customer>()); }
    var rows = await LoadRows(Array.Empty<Order>(), Load);
    Eq(rows.Count, 0);
    Eq(calls, 0);
});

